    # MPLT
    def Pack(self, builder):
        if self.ID is not None:
            ID = builder.CreateString(self.ID)
        if self.PLANNER is not None:
            PLANNER = builder.CreateString(self.PLANNER)
        if self.OBJECT_ID is not None:
            OBJECT_ID = builder.CreateString(self.OBJECT_ID)
        if self.TARGET_OBJECT_ID is not None:
            TARGET_OBJECT_ID = builder.CreateString(self.TARGET_OBJECT_ID)
        if self.REFERENCE_FRAME is not None:
            REFERENCE_FRAME = self.REFERENCE_FRAME.Pack(builder)
        if self.REQUEST is not None:
            REQUEST = self.REQUEST.Pack(builder)
        if self.ERROR_CODE is not None:
            ERROR_CODE = builder.CreateString(self.ERROR_CODE)
        if self.ERROR_MESSAGE is not None:
            ERROR_MESSAGE = builder.CreateString(self.ERROR_MESSAGE)
        if self.BURNS is not None:
            BURNSlist = []
            for i in range(len(self.BURNS)):
                BURNSlist.append(self.BURNS[i].Pack(builder))
            MPLStartBURNSVector(builder, len(self.BURNS))
            for i in reversed(range(len(self.BURNS))):
                builder.PrependUOffsetTRelative(BURNSlist[i])
            BURNS = builder.EndVector()
        if self.ARCS is not None:
            ARCSlist = []
            for i in range(len(self.ARCS)):
                ARCSlist.append(self.ARCS[i].Pack(builder))
            MPLStartARCSVector(builder, len(self.ARCS))
            for i in reversed(range(len(self.ARCS))):
                builder.PrependUOffsetTRelative(ARCSlist[i])
            ARCS = builder.EndVector()
        if self.SOLVER is not None:
            SOLVER = self.SOLVER.Pack(builder)
        if self.OPTIONS is not None:
            OPTIONSlist = []
            for i in range(len(self.OPTIONS)):
                OPTIONSlist.append(self.OPTIONS[i].Pack(builder))
            MPLStartOPTIONSVector(builder, len(self.OPTIONS))
            for i in reversed(range(len(self.OPTIONS))):
                builder.PrependUOffsetTRelative(OPTIONSlist[i])
            OPTIONS = builder.EndVector()
        if self.TRAJECTORY is not None:
            TRAJECTORY = self.TRAJECTORY.Pack(builder)
        if self.PHASING is not None:
            PHASING = self.PHASING.Pack(builder)
        if self.RELATIVE is not None:
            RELATIVE = self.RELATIVE.Pack(builder)
        if self.RENDEZVOUS is not None:
            RENDEZVOUS = self.RENDEZVOUS.Pack(builder)
        if self.GEOMETRY is not None:
            GEOMETRY = self.GEOMETRY.Pack(builder)
        MPLStart(builder)
        if self.ID is not None:
            MPLAddID(builder, ID)
        MPLAddCREATED_AT_MS(builder, self.CREATED_AT_MS)
        if self.PLANNER is not None:
            MPLAddPLANNER(builder, PLANNER)
        MPLAddPROBLEM(builder, self.PROBLEM)
        MPLAddPLAN_EPOCH_MS(builder, self.PLAN_EPOCH_MS)
        if self.OBJECT_ID is not None:
            MPLAddOBJECT_ID(builder, OBJECT_ID)
        if self.TARGET_OBJECT_ID is not None:
            MPLAddTARGET_OBJECT_ID(builder, TARGET_OBJECT_ID)
        if self.REFERENCE_FRAME is not None:
            MPLAddREFERENCE_FRAME(builder, REFERENCE_FRAME)
        if self.REQUEST is not None:
            MPLAddREQUEST(builder, REQUEST)
        MPLAddSTATUS(builder, self.STATUS)
        if self.ERROR_CODE is not None:
            MPLAddERROR_CODE(builder, ERROR_CODE)
        if self.ERROR_MESSAGE is not None:
            MPLAddERROR_MESSAGE(builder, ERROR_MESSAGE)
        if self.BURNS is not None:
            MPLAddBURNS(builder, BURNS)
        if self.ARCS is not None:
            MPLAddARCS(builder, ARCS)
        MPLAddTOTAL_DELTA_V_KM_S(builder, self.TOTAL_DELTA_V_KM_S)
        MPLAddTOTAL_TIME_S(builder, self.TOTAL_TIME_S)
        MPLAddTOTAL_DELTA_MASS_KG(builder, self.TOTAL_DELTA_MASS_KG)
        if self.SOLVER is not None:
            MPLAddSOLVER(builder, SOLVER)
        if self.OPTIONS is not None:
            MPLAddOPTIONS(builder, OPTIONS)
        if self.TRAJECTORY is not None:
            MPLAddTRAJECTORY(builder, TRAJECTORY)
        if self.PHASING is not None:
            MPLAddPHASING(builder, PHASING)
        if self.RELATIVE is not None:
            MPLAddRELATIVE(builder, RELATIVE)
        if self.RENDEZVOUS is not None:
            MPLAddRENDEZVOUS(builder, RENDEZVOUS)
        if self.GEOMETRY is not None:
            MPLAddGEOMETRY(builder, GEOMETRY)
        MPL = MPLEnd(builder)
        return MPL
